// Better actions for late/changed iiko alerts. Kitchen-to-kitchen transit is informational only.
(function(){
  function lateDocumentUrl(a){const q=new URLSearchParams({id:String(a.meta?.documentId||''),date:a.businessDate||'',point:a.pointCode||''});return `../document/?${q.toString()}`}
  function isKitchenTransit(a){const meta=a.meta||{};const from=String(meta.fromStore||meta.fromStoreName||meta.sourceStore||meta.sourceWarehouse||'').toLowerCase();const to=String(meta.toStore||meta.toStoreName||meta.destinationStore||meta.destinationWarehouse||'').toLowerCase();const status=String(meta.status||meta.documentStatus||'').toLowerCase();const text=[a.title,a.description,a.pointName,meta.route,meta.fromStore,meta.toStore,meta.fromStoreName,meta.toStoreName].filter(Boolean).join(' ').toLowerCase();const knownKitchenRoute=(text.includes('правда кухня')&&text.includes('бухара кухня'))||(text.includes('бухара кухня')&&text.includes('правда кухня'));return status==='warehouse_transit'||(from.includes('кухн')&&to.includes('кухн'))||knownKitchenRoute}
  const oldAlertCard=alertCard;
  alertCard=function(a){if(a.kind!=='late_iiko'&&a.kind!=='changed_iiko')return oldAlertCard(a);const url=lateDocumentUrl(a),key=a.meta?.externalKey||'',doc=esc(a.meta?.documentNumber||''),date=esc(a.businessDate||''),point=esc(a.pointName||'');if(isKitchenTransit(a)){return `<article class="alert"><div class="alert-head"><div><h3>ℹ Изменено перемещение между кухнями</h3><div class="alert-meta">${esc(a.pointName||'')} · ${esc(fmtDate(a.businessDate))}</div></div><div class="alert-actions">${key?`<button class="transit-ack secondary" data-key="${esc(key)}" data-doc="${doc}" ${state.busy?'disabled':''}>Принято во внимание</button>`:''}</div></div><p>${esc(a.description||'')} Изменение учтено как движение между кухнями; пересчёт точки продаж не требуется.</p></article>`}if(a.kind==='changed_iiko')return oldAlertCard(a);const recalc=key?`<button class="recalc-iiko" data-key="${esc(key)}" data-doc="${doc}" data-date="${date}" data-point="${point}" ${state.busy?'disabled':''}>Пересчитать</button>`:'';const dismiss=key?`<button class="late-dismiss secondary" data-key="${esc(key)}" data-doc="${doc}" ${state.busy?'disabled':''}>Учтено без пересчёта</button>`:'';return `<article class="alert ${a.severity==='error'?'error':''}"><div class="alert-head"><div><h3>${a.severity==='error'?'⛔':'⚠'} ${esc(a.title)}</h3><div class="alert-meta">${esc(a.pointName||'')} · ${esc(fmtDate(a.businessDate))}</div></div><div class="alert-actions">${recalc}<a class="secondary admin-link" href="${url}">Открыть документ</a>${dismiss}</div></div><p>${esc(a.description||'')}</p></article>`};
  function removeAlert(key,kind){const removed=state.data?.alerts?.find(a=>a.kind===kind&&a.meta?.externalKey===key);if(!removed)return;state.data.alerts=state.data.alerts.filter(a=>!(a.kind===kind&&a.meta?.externalKey===key));if(state.data.summary){if(removed.severity==='warning')state.data.summary.warnings=Math.max(0,Number(state.data.summary.warnings||0)-1);if(removed.severity==='error')state.data.summary.errors=Math.max(0,Number(state.data.summary.errors||0)-1)}}
  async function acknowledgeTransit(key,number){if(!key||state.busy)return;const snapshot=state.data?JSON.parse(JSON.stringify(state.data)):null;removeAlert(key,'changed_iiko');state.message=`Документ${number?` №${number}`:''}: сохраняем отметку…`;render();try{await rpc('admin_acknowledge_iiko_change',{p_token:state.token,p_external_key:key,p_comment:'Изменение перемещения между кухнями просмотрено и принято во внимание'});state.busy=false;state.message=`Документ${number?` №${number}`:''}: принято во внимание.`;render();await load()}catch(e){if(snapshot)state.data=snapshot;state.busy=false;state.message=e.message||'Не удалось сохранить отметку';render()}}
  async function dismissLate(key,number){if(!key||state.busy)return;if(!confirm(`Отметить перемещение${number?` №${number}`:''} как учтённое БЕЗ пересчёта?\n\nИспользуйте это только если изменение не должно влиять на остатки и продажи.`))return;const snapshot=state.data?JSON.parse(JSON.stringify(state.data)):null;removeAlert(key,'late_iiko');render();try{await rpc('admin_resolve_late_document',{p_token:state.token,p_external_key:key,p_action:'dismiss',p_comment:'Предупреждение просмотрено администратором; принято решение не пересчитывать документ',p_actor:'Администратор'});state.busy=false;await load()}catch(e){if(snapshot)state.data=snapshot;state.busy=false;state.message=e.message||'Не удалось сохранить отметку';render()}}
  const oldBind=bind;bind=function(){oldBind();document.querySelectorAll('.late-dismiss').forEach(b=>b.onclick=()=>dismissLate(b.dataset.key,b.dataset.doc));document.querySelectorAll('.transit-ack').forEach(b=>b.onclick=()=>acknowledgeTransit(b.dataset.key,b.dataset.doc))};
})();
